using System;using System.IO;using System.Linq;using UnityEngine;using UnityEngine.SceneManagement;using UnityEditor;using Newtonsoft.Json.Linq;
public static class StreetFrontFinalCheck {public static string Run(){var scene=SceneManager.GetActiveScene();var map=scene.GetRootGameObjects().Single(v=>v.name=="MyeongjiMap");var prefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/_Game/Prefabs/Myeongji/MyeongjiMap.prefab");var ids=(JArray)JObject.Parse(File.ReadAllText("Docs/MapLayout/Myeongji/layout.json"))["lots"];int modified=0,preserved=0;foreach(var lot in ids){string id=(string)lot[0];var f=map.GetComponentsInChildren<MeshFilter>().Single(v=>v.name=="AB01_"+id+".001");var p=prefab.GetComponentsInChildren<MeshFilter>().Single(v=>v.name==f.name);if(f.sharedMesh==null||f.sharedMesh!=p.sharedMesh||f.GetComponent<MeshCollider>().sharedMesh!=f.sharedMesh)throw new Exception("Mesh reference mismatch "+id);if(f.GetComponent<Renderer>().sharedMaterials.Length!=f.sharedMesh.subMeshCount)throw new Exception("Material mismatch "+id);if(new[]{"A01","A02","B01"}.Contains(id)){preserved++;continue;}if(!AssetDatabase.GetAssetPath(f.sharedMesh).Contains("StreetFronts"))throw new Exception("Unfinished "+id);modified++;}if(scene.isDirty||scene.GetRootGameObjects().Any(g=>g.name.StartsWith("Temporary_FacadePreview")))throw new Exception("Unsaved or preview object left");var result=new JObject{{"buildings",ids.Count},{"refined",modified},{"originalDetailedPreserved",preserved},{"sceneAndPrefabMatch",true},{"playTest",false}};File.WriteAllText("Docs/MapLayout/Myeongji/streetfront_final_check.json",result.ToString());return result.ToString();}}
